if let Some((access, workspace)) = workspace_access.clone() {
    let core_file_tools = filetools::register_core_file_tools(
        &registry,
        gateway.as_ref(),
        Arc::clone(&access),
        workspace.clone(),
        Arc::clone(&deps.clock),
        Arc::new(filehistory::FileHistoryChangeLog::new(file_history.clone())),
        &budget,
    );
    stagefiles::register_stage_files(
        &registry,
        gateway.as_ref(),
        session_files.clone(),
        access.clone(),
        workspace.clone(),
        &budget,
    );

pub struct FileHistoryChangeLog {
    history: Arc<FileHistoryService>,
    runtime: tokio::runtime::Handle,
}
impl FileHistoryChangeLog {
    pub fn new(history: Arc<FileHistoryService>) -> Self {
        Self {
            history,
            runtime: tokio::runtime::Handle::current(),
        }
    }
}
impl crate::filetools::FileChangeLog for FileHistoryChangeLog {
    fn record(&self, record: crate::filetools::FileModificationRecord) {
        self.runtime
            .block_on(self.history.capture_from_disk(&record.path, "tool"));
    }
}

